from pathlib import Path
import re,json
R=Path(__file__).resolve().parents[2];O=R/'outputs/closure-r4';W=R/'work/closure'
d=json.loads((O/'validation-final.json').read_text(encoding='utf8'))
review=json.loads((O/'review-index.json').read_text(encoding='utf8')) if(O/'review-index.json').exists() else {'summary':'Revisões independentes pendentes. Nenhum aceite presumido.','reviews':[]}
css=re.search(r'<style>(.*?)</style>',(R/'work/dashboard.template.html').read_text(encoding='utf8'),re.S).group(1)
css+='\npre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 Consolas,monospace;background:#edf2f3;padding:16px;max-height:650px;overflow:auto} .hash{overflow-wrap:anywhere;font-family:Consolas,monospace} .field dd{white-space:pre-wrap} .notice p{max-width:100ch} .plainlist{max-width:95ch} .table td{overflow-wrap:anywhere} .table{min-width:480px} summary{overflow-wrap:anywhere} .gold>h3{margin:10px 0 16px} .main{max-width:1600px} .table th{letter-spacing:0} .table td p{margin:8px 0} button{min-height:40px} .idbutton{padding:3px 0} @media(max-width:680px){.table{font-size:13px}.nav button{min-height:44px}pre{padding:12px}.hash{font-size:12px}.detailbar h2{max-width:100%}.controls label{min-width:140px}}'
def pack(v):return json.dumps(v,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
html='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Vilumo Fit · AE Closure r4</title><style>@@CSS@@</style></head><body><a class="sr" href="#main">Ir para o relatório</a><div class="shell"><aside class="sidebar"><div class="brand">Vilumo Fit</div><div class="subbrand">Adaptive Engine · Closure r4</div><nav id="nav" class="nav" aria-label="Seções da auditoria"></nav><div class="sidefoot">22 outubro 2026<br>Mesmos 89 registros<br>Sem runtime · sem Figma<br><br>Julgamento documental. Aprovação esportiva/humana separada.</div></aside><main id="main" class="main"><header class="top"><div><h1>Fechamento do Adaptive Engine</h1><p id="revision"></p></div><div class="verdict"><strong>NO-GO</strong>Autoridade prescritiva final de treino</div></header><div id="panels"></div><footer class="footer">Fontes e r3 preservadas por hash. Novos witnesses são explícitos. Nenhuma implementação, edição de Figma ou expansão de escopo.</footer></main></div><script id="report-data" type="application/json">@@DATA@@</script><script id="review-data" type="application/json">@@REVIEWS@@</script><script>@@JS@@</script></body></html>'''
html=html.replace('@@CSS@@',css).replace('@@DATA@@',pack(d)).replace('@@REVIEWS@@',pack(review)).replace('@@JS@@',(W/'dashboard.js').read_text(encoding='utf8'))
(O/'dashboard.html').write_text(html,encoding='utf8');print('Dashboard rendered',len(html.encode('utf8')))
